{
  "spells": [
    {
      "id": "spell_wind_04",
      "theory": "听风术把一缕魔力送入近处空气，使其在有限范围内来回轻荡，施术者借助回音分辨风向与微弱声息。石墙、厚木板或堆实的土坯会截断这缕气流，因而无法探知墙后情形。它只读取空气自身的动静，不使空气加速，也不产生推力，封闭空间内空气不流通时便没有可用的回声。",
      "casting": "掌心朝下，在面前缓缓横划一道弧线，同时从指缝间放出魔力，让气流贴着手臂外侧绕行一圈。",
      "failure": "魔力散得太快时，耳边只剩自己呼吸的杂音；若弧线划得过急，会误把近处风声当作远处脚步，得到错误方向。",
      "counters": [
        "在施术者与目标之间张挂厚布或草帘，气流被挡后回音明显减弱。",
        "持续敲击石块或木梆制造杂乱声响，可让听风者难以分辨单一方向。"
      ],
      "socialConsequences": "河谷的猎人、渡船人和巡夜者常请会此术的人帮忙判断天气或来船方向，乡约见证下口头约定报酬即可。中陆城里，客栈掌柜愿意用它检查后院动静，但若用来探听邻家谈话，会被视为侵犯私事而遭到追究。港口的装卸工头欢迎用它预判阵风，却反对有人借机窥探货舱内封存的货物。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "刚学会时风声混杂，只能大致辨出迎面或背面的方向。",
        "熟练后能区分两股相近气流，仍限于近处开阔地。",
        "控制更稳时，可听清三米内轻物被风吹动的细响。",
        "更高熟练度减少误判，仍不能穿透石墙或厚板。"
      ]
    },
    {
      "id": "spell_wind_05",
      "theory": "晾谷风将魔力铺展在谷物堆表层，使空气在谷粒缝隙间缓慢穿行，带走湿气。它只加快表面水汽离开，不发热也不翻动谷粒，因此需要人在旁用木耙定时翻搅。若谷堆过厚或场地不通风，湿气会滞留在下层，法术效果随之减弱。",
      "casting": "双手在谷堆上方交替画小圈，由内向外扩展，同时持续送出魔力，直到最外圈空气开始流动。",
      "failure": "魔力分布不均时，只有局部谷粒变干，其余部分仍潮；若中途停止画圈，气流会突然中断，已排出的湿气可能回渗表层。",
      "counters": [
        "用席子或厚布盖住谷堆，湿气无法散出，法术便失去作用。",
        "在近处点燃湿草制造浓烟，烟尘混入气流会污染谷物，使晾晒无法继续。"
      ],
      "socialConsequences": "河谷农户在收获季常请邻里互助晾谷，乡约见证下以换工或少量粮食作酬。中陆粮商愿雇人施术缩短入仓时间，但要求施术者不碰谷堆以免混入杂物。港口仓库管理员接受它用于干燥受潮的散货，前提是不影响堆存和防火，若因操作不当造成霉变，港务会追究货损责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常漏掉边角，谷堆中央干得慢，需要多次补施。",
        "熟练后气流覆盖较匀，仍需按刻翻动才能避免下层返潮。",
        "控制精细者能避开已干区域，减少谷物被吹散落地。",
        "更高熟练度使湿度判断更准，仍无法穿透厚谷层。"
      ]
    },
    {
      "id": "spell_wind_06",
      "theory": "缓坠术在坠落者身周聚起一层缓慢流动的空气垫，使下降速度变缓。空气垫只托住一个人的重量，对捆扎的货箱、推车或牲畜没有足够承托力；它也不改变坠落方向，只能减轻落地冲击。若施术者与坠落者之间隔有石墙或密林，魔力难以维持连续气流，效果会提前消散。",
      "casting": "手掌张开对准坠落者，自下而上缓缓抬臂，同时让魔力沿手臂形成上升气流，持续到对方接近地面。",
      "failure": "魔力输出不稳时，气流会一阵阵断续，坠落者忽快忽慢，容易在最后一段失稳侧倒；若抬臂过快，空气垫可能只护住上半身，腿部仍受撞击。",
      "counters": [
        "在坠落路径上伸出长竿或网具，可提前接住人，使缓坠术不再必要。",
        "用强风或重物扰乱施术者周围气流，可使其无法维持稳定输出。"
      ],
      "socialConsequences": "河谷的采药人和修屋匠在攀爬时会请人备好此术，乡约见证下按次付酬。中陆城里的行会要求高空作业者须有同伴持术，否则出事由雇主担责；若在闹市无故对路人施术，会被视为干扰公共秩序。港口装卸区，船主和工头接受它用于桅杆作业，但若坠落的货物未受保护，港务只追究操作者责任，不因法术而免责。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "刚入门时气流断续，落地仍会踉跄，需旁人搀扶。",
        "熟练后能维持稳定托力，使一人平稳落地而不受伤。",
        "控制精准者可在最后一刻收力，避免把人推离落点。",
        "更高熟练度使持续更可靠，仍不能托起重货或多人。"
      ]
    }
  ]
}
